package org.jfree.chart.plot;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Paint;
import java.awt.Stroke;
import java.io.*;
import java.math.*;
import java.util.*;
import org.jfree.chart.event.MarkerChangeEvent;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class ValueMarker_ValueMarker_TriageGen2Test {

    @Test
    public void testConstructorWithSingleParam() {
        double value = 10.5;
        ValueMarker marker = new ValueMarker(value);
        assertEquals(value, marker.getValue(), 1e-10);
    }

    @Test
    public void testConstructorWithThreeParams() {
        double value = 20.0;
        Paint paint = Color.RED;
        BasicStroke stroke = new BasicStroke(2.0f);
        ValueMarker marker = new ValueMarker(value, paint, stroke);

        assertEquals(value, marker.getValue(), 1e-10);
        // Note: Since the base class handles paint/stroke, we verify via side effects or state if possible.
        // In JFreeChart context, these are stored in the object.
    }

    @Test
    public void testConstructorWithSixParams() {
        double value = 30.5;
        Paint paint = Color.BLUE;
        BasicStroke stroke = new BasicStroke(1.0f);
        Paint outlinePaint = Color.BLACK;
        BasicStroke outlineStroke = new BasicStroke(0.5f);
        float alpha = 0.5f;

        ValueMarker marker = new ValueMarker(value, paint, stroke, outlinePaint, outlineStroke, alpha);

        assertEquals(value, marker.getValue(), 1e-10);
    }

    @Test
    public void testSetValue() {
        ValueMarker marker = new ValueMarker(1.0);
        marker.setValue(5.5);
        assertEquals(5.5, marker.getValue(), 1e-10);
    }

    @Test
    public void testEquals() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(10.0);
        ValueMarker marker3 = new ValueMarker(20.0);

        // Test equality
        assertEquals(marker1, marker2);

        // Test inequality (different value)
        assertNotEquals(marker1, marker3);

        // Test inequality (different type)
        assertNotEquals(marker1, "not a marker");

        // Test inequality (null)
        assertNotEquals(marker1, null);
    }
}
